import org.apache.nifi.processor.io.StreamCallback
import org.apache.nifi.dbcp.DBCPService
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets

def ff = session.get()
if (!ff) return

// Resolve Snowflake DBCP by name — stable across REPLACE deployments
def lookup = context.controllerServiceLookup
def sfPool = lookup.getControllerServiceIdentifiers(DBCPService.class)
    .findResult { id ->
        lookup.getControllerServiceName(id) == 'Snowflake Connection Pool'
            ? lookup.getControllerService(id) as DBCPService : null
    }
if (!sfPool) {
    log.error("Snowflake Connection Pool service not found")
    session.transfer(ff, REL_FAILURE)
    return
}

try {
    def destSchema = ff.getAttribute('destination.schema.name') ?: ''
    def destTable  = ff.getAttribute('destination.table.name')  ?: ''
    def eventType  = '#{Snapshot Journal Event Type}'

    // ── 1. Parse snapshot rows ─────────────────────────────────────────────
    def raw = new String(session.read(ff).bytes, StandardCharsets.UTF_8)
    def rows = raw.split('\n').collect { it.trim() }.findAll { it }
                  .collect { new JsonSlurper().parseText(it) }
    if (!rows) { session.transfer(ff, REL_FAILURE); return }

    // ── 2. Wait for OOTB connector to create journal table ────────────────
    // The connector creates {TABLE}_JOURNAL_{generation}_1 via its DDL path.
    // With Starting CDC Position = Earliest it fires before the snapshot runs.
    def journalTableName = null
    for (int i = 0; i < 6 && !journalTableName; i++) {
        if (i > 0) Thread.sleep(5000L)
        def sfConn = sfPool.getConnection()
        try {
            def st = sfConn.prepareStatement(
                "SELECT table_name FROM information_schema.tables " +
                "WHERE table_schema = UPPER(?) AND table_name ILIKE UPPER(CONCAT(?, '_JOURNAL_%')) " +
                "LIMIT 1")
            st.setString(1, destSchema); st.setString(2, destTable)
            def rs = st.executeQuery()
            if (rs.next()) journalTableName = rs.getString(1)
            rs.close(); st.close()
        } finally { sfConn.close() }
    }

    if (!journalTableName) {
        log.warn("No journal table found for {}.{} after retries — skipping snapshot journal tee",
                 destSchema, destTable)
        session.transfer(ff, REL_FAILURE)
        return
    }

    // ── 3. Identify PK columns from journal table schema ──────────────────
    def pkCols = []
    def jConn = sfPool.getConnection()
    try {
        def st = jConn.prepareStatement(
            "SELECT column_name FROM information_schema.columns " +
            "WHERE table_schema = UPPER(?) AND table_name = UPPER(?) " +
            "AND column_name ILIKE 'PRIMARY_KEY__%'")
        st.setString(1, destSchema); st.setString(2, journalTableName)
        def rs = st.executeQuery()
        while (rs.next())
            pkCols << rs.getString(1).replaceFirst('(?i)^PRIMARY_KEY__', '').toUpperCase()
        rs.close(); st.close()
    } finally { jConn.close() }

    // ── 4. Transform to journal format ────────────────────────────────────
    def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS")
    sdf.setTimeZone(java.util.TimeZone.getTimeZone('UTC'))
    def seenAt = sdf.format(new java.util.Date())

    def journalRows = rows.collect { row ->
        def jr = [:]
        row.each { k, v ->
            def upper = k.toString().toUpperCase()
            // Skip Snowflake metadata columns — not present in source or journal table
            if (upper.startsWith('_SNOWFLAKE_')) return
            // Skip fields already in journal format (from previous pass)
            if (upper.startsWith('PRIMARY_KEY__') || upper.startsWith('PAYLOAD__') ||
                upper in ['EVENT_TYPE','SEEN_AT','LEAST_SIGNIFICANT_POSITION',
                          'MOST_SIGNIFICANT_POSITION','SF_METADATA']) return
            if (pkCols.contains(upper)) jr["PRIMARY_KEY__${upper}"] = v
            jr["PAYLOAD__${upper}"] = v
        }
        jr['LEAST_SIGNIFICANT_POSITION'] = 0
        jr['MOST_SIGNIFICANT_POSITION']  = 0
        jr['EVENT_TYPE']                 = eventType
        jr['SEEN_AT']                    = seenAt
        jr['SF_METADATA']                = null
        jr
    }

    // ── 5. Write JSON Lines output ─────────────────────────────────────────
    def output = journalRows.collect { JsonOutput.toJson(it) }.join('\n')
    ff = session.write(ff, { inp, out ->
        out.write(output.getBytes(StandardCharsets.UTF_8))
    } as StreamCallback)
    ff = session.putAttribute(ff, 'journal.table.name', journalTableName)
    session.transfer(ff, REL_SUCCESS)

} catch (Exception e) {
    log.error('Convert Snapshot to Journal Format failed: {}', e.message, e)
    session.transfer(ff, REL_FAILURE)
}
